import {readFile,readdir,mkdir,writeFile}from'node:fs/promises';import{join}from'node:path';import{discoverServices}from'../site/transaction-discovery.js';
const report={sourceSha:process.env.SOURCE_SHA,scope:'Historical Google email follow-up; not current Google index or ranking acceptance',htmlFiles:0,datasetNodes:[],invalidJsonLd:[],queries:[],status:'PASS'};
async function walk(p){for(const e of await readdir(p,{withFileTypes:true})){if(e.name.startsWith('.')||['node_modules','diagnostics','artifacts','test'].includes(e.name))continue;const f=join(p,e.name);if(e.isDirectory())await walk(f);else if(e.name.endsWith('.html')){report.htmlFiles++;const html=await readFile(f,'utf8');for(const m of html.matchAll(/<script\b[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)){try{const data=JSON.parse(m[1]);const scan=x=>{if(!x||typeof x!=='object')return;if(x['@type']==='Dataset'||Array.isArray(x['@type'])&&x['@type'].includes('Dataset'))report.datasetNodes.push({path:f,name:x.name,descriptionPresent:!!x.description,licensePresent:!!x.license,creatorPresent:!!x.creator});for(const v of Object.values(x))if(typeof v==='object')Array.isArray(v)?v.forEach(scan):scan(v);};scan(data);}catch(e){report.invalidJsonLd.push({path:f,error:e.message});}}}}}
await walk('site');const records=JSON.parse(await readFile('site/transaction-discovery-data.json','utf8'));for(const [query,expected]of [['زيارة قريب او صديق دبي','تأشيرة-زيارة-قريب-أو-صديق-لدخول-واحد-في-دبي'],['إلغاء تصريح مغادرة للمخالفين','cancel-departure-permit-icp'],['الهيئة الاتحادية للهوية والجمارك أمن المنافذ دبي',null]]){const results=discoverServices(records,{query});report.queries.push({query,evidence:'Observed query in September 2026 Search Console monthly email; one click, not query-page association',expected,actual:results.slice(0,5).map(x=>({slug:x.s,name:x.n||x.a||x.title})),status:expected?(results[0]?.s===expected?'PASS':'FAIL'):'AUTHORITY_AND_JURISDICTION_AMBIGUOUS; NO_SINGLE_TRANSACTION_ASSERTED'});}
if(report.invalidJsonLd.length||report.datasetNodes.some(x=>!x.descriptionPresent)||report.queries.some(x=>x.status==='FAIL'))report.status='FAIL';await mkdir('diagnostics/google-email-followup-20261119',{recursive:true});await writeFile('diagnostics/google-email-followup-20261119/report.json',JSON.stringify(report,null,2));console.log(JSON.stringify(report));if(report.status==='FAIL')process.exitCode=1;